async function getKey(permission: string): Promise<string> {
  if (permission === "No") {
    return "";
  }
  const { results: keys } = await masterClient.getKeys();

  if (permission === "Search") {
    const key = keys.find((key) => key.name === "Default Search API Key")?.key;
    return key || "";
  }

  if (permission === "Chat") {
    const key = keys.find((key) => key.name === "Default Chat API Key")?.key;
    return key || "";
  }

  if (permission === "Admin") {
    const key = keys.find((key) => key.name === "Default Admin API Key")?.key;
    return key || "";
  }
  return MASTER_KEY;
}

async function getClient(permission: string): Promise<Meilisearch> {
  if (permission === "No") {
    const anonymousClient = new Meilisearch({
      host: HOST,
      defaultWaitOptions: { interval: 10 },
    });
    return anonymousClient;
  }

  if (permission === "Search") {
    const searchKey = await getKey(permission);
    const searchClient = new Meilisearch({
      host: HOST,
      apiKey: searchKey,
      defaultWaitOptions: { interval: 10 },
    });
    return searchClient;
  }

  if (permission === "Admin") {
    const adminKey = await getKey(permission);
    const adminClient = new Meilisearch({
      host: HOST,
      apiKey: adminKey,
      defaultWaitOptions: { interval: 10 },
    });
    return adminClient;
  }

  return masterClient;
}

const clearAllIndexes = async (config: Config): Promise<void> => {
  const client = new Meilisearch(config);
  const { results } = await client.getRawIndexes();

  await Promise.all(
    results.map((v) =>
      client.index(v.uid).delete().waitTask({ timeout: 60_000 }),
    ),
  );
};

const clearNetworkTopology = async (
  client: Meilisearch = masterClient,
): Promise<void> => {
  await client.updateExperimentalFeatures({ network: true });

  let network;
  try {
    network = await client.getNetwork();
  } catch {
    return;
  }

  const remotes = Object.fromEntries(
    Object.keys(network.remotes ?? {}).map((name) => [name, null]),
  );
  const shards = Object.fromEntries(
    Object.keys(network.shards ?? {}).map((name) => [name, null]),
  );

  const result = await client.updateNetwork({
    leader: null,
    self: null,
    remotes,
    shards,
  });

  if ("taskUid" in result && result.taskUid != null) {
    await client.tasks.waitForTask(result, { timeout: 60_000 });
  }
};

